/* ========================================
   Unlimited Tube - Free HD Videos
   CSS Stylesheet
   ======================================== */

/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* Colors - Pornhub Red Theme */
    --primary-color: #ffa500;
    --primary-dark: #e89a00;
    --primary-light: #ffbf00;
    --secondary-color: #ec7a00;
    --accent-color: #ffcc33;

    /* Backgrounds */
    --dark-1: #222222;
    --dark-2: #1a1a1a;
    --dark-3: #151515;
    --dark-4: #2d0505;

    /* Text Colors */
    --white: #ffffff;
    --gray-100: #f5f5f5;
    --gray-300: #e0e0e0;
    --gray-500: #888888;
    --gray-700: #444444;
    --gray-900: #111111;

    /* Spacing */
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;

    /* Typography */
    --font-heading: 'Rajdhani', sans-serif;
    --font-body: 'Rajdhani', sans-serif;

    /* Transitions */
    --transition-fast: 0.2s ease;
    --transition-normal: 0.3s ease;

    /* Shadows */
    --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.5);
}

html {
    font-size: 17px;
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    font-weight: 400;
    font-size: 1rem;
    line-height: 1.5;
    color: var(--gray-100);
    background-color: var(--dark-1);
    overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    font-weight: 700;
    line-height: 1.2;
    color: var(--white);
    text-transform: uppercase;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition-fast);
}

a:hover {
    color: var(--primary-color);
}

img {
    max-width: 100%;
    height: auto;
}

/* Utility Classes */
.container {
    max-width: 1600px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

.text-center {
    text-align: center;
}

.text-white {
    color: var(--white) !important;
}

.text-primary {
    color: var(--primary-color) !important;
}

.text-gray-500 {
    color: var(--gray-500) !important;
}

/* ========================================
   Buttons
   ======================================== */

.btn {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.5rem;
    font-size: 0.95rem;
    font-weight: 600;
    font-family: var(--font-heading);
    text-transform: uppercase;
    cursor: pointer;
    transition: var(--transition-fast);
    border: none;
    white-space: nowrap;
}

.btn-red {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--secondary-color) 100%);
    color: var(--white);
    box-shadow: 0 4px 15px rgba(255, 165, 0, 0.4);
}

.btn-red:hover {
    background: linear-gradient(135deg, var(--secondary-color) 0%, var(--primary-color) 100%);
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(255, 165, 0, 0.6);
}

.btn-large {
    padding: 1rem 2rem;
    font-size: 1.1rem;
}

.btn-transparent {
    background: transparent;
    border: 1px solid var(--gray-500);
    color: var(--gray-500);
}

.btn-transparent:hover {
    border-color: var(--white);
    color: var(--white);
}

.btn-icon {
    padding: 0.6rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: transparent;
    border: 1px solid var(--gray-700);
    color: var(--gray-500);
    border-radius: 50%;
    margin-left: 0.25rem;
}

.btn-icon:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.btn-user {
    padding: 0.5rem 1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: var(--dark-3);
    border: 1px solid var(--primary-color);
    color: var(--primary-color);
    border-radius: 5px;
}

.btn-user:hover {
    background: var(--primary-color);
    color: var(--white);
}

/* ========================================
   Navigation
   ======================================== */

.navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    padding: 0.75rem var(--spacing-sm);
    background-color: var(--dark-1);
    z-index: 1000;
    border-bottom: 1px solid var(--gray-700);
    transition: var(--transition-fast);
}

.nav-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 2rem;
}

.nav-logo {
    font-family: var(--font-heading);
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--white);
    padding: 0.5rem 1rem;
    border: 2px solid var(--primary-color);
    border-radius: 50px;
    transition: var(--transition-fast);
}

.nav-logo:hover {
    background: var(--primary-color);
    color: var(--white) !important;
}

.logo-text {
    color: var(--primary-color) !important;
    letter-spacing: 2px;
}

.nav-search {
    flex: 1;
    max-width: 400px;
    position: relative;
}

.nav-search input {
    width: 100%;
    padding: 0.75rem 1rem 0.75rem 2.5rem;
    background: var(--dark-3);
    border: 1px solid var(--gray-700);
    border-radius: 50px;
    color: var(--gray-100);
    font-family: var(--font-heading);
    font-size: 0.95rem;
    transition: var(--transition-fast);
}

.nav-search input:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 2px rgba(255, 165, 0, 0.3);
}

.nav-search i {
    position: absolute;
    right: 1rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--gray-500);
    cursor: pointer;
}

.nav-actions {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

/* ========================================
   Site Header
   ======================================== */

.site-header {
    background: linear-gradient(180deg, var(--dark-1) 0%, var(--dark-2) 100%);
    padding: 3rem 0 2rem;
    border-bottom: 1px solid var(--gray-700);
    position: relative;
    overflow: hidden;
}

.site-header::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(90deg, var(--primary-color), transparent);
}

.header-content {
    text-align: center;
    max-width: 900px;
    margin: 0 auto;
}

header h1.logo-text {
    font-size: 3.5rem;
    margin-bottom: 0.5rem;
    background: linear-gradient(180deg, var(--primary-color) 0%, var(--secondary-color) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: 4px;
}

.header-subtitle {
    font-size: 1.2rem;
    color: var(--gray-500);
    margin-bottom: 2rem;
    font-weight: 400;
}

.search-header {
    position: relative;
    max-width: 700px;
    margin: 0 auto 1.5rem;
}

.search-header input {
    width: 100%;
    padding: 1rem 1.5rem 1rem 4rem;
    background: var(--dark-3);
    border: 2px solid var(--primary-color);
    border-radius: 50px;
    color: var(--white);
    font-family: var(--font-heading);
    font-size: 1rem;
    transition: var(--transition-fast);
}

.search-header input:focus {
    outline: none;
    box-shadow: 0 0 20px rgba(255, 165, 0, 0.5);
}

.search-header input::placeholder {
    color: var(--gray-500);
}

.search-header .btn-red {
    position: absolute;
    right: 2rem;
    top: 50%;
    transform: translateY(-50%);
    padding: 0.7rem 1.5rem;
    border: none;
    border-radius: 50px;
    font-weight: 600;
}

.header-filters {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
}

.filter-group {
    display: flex;
    gap: 0.5rem;
}

.filter-btn {
    padding: 0.75rem 1.5rem;
    background: var(--dark-3);
    border: 1px solid var(--gray-700);
    color: var(--gray-500);
    border-radius: 50px;
    text-transform: uppercase;
    font-family: var(--font-heading);
    font-size: 0.9rem;
    font-weight: 600;
    transition: var(--transition-fast);
    cursor: pointer;
    min-width: 120px;
}

.filter-btn.active,
.filter-btn:hover {
    background: var(--primary-color);
    border-color: var(--primary-color);
    color: var(--white);
}

/* ========================================
   Main Content
   ======================================== */

.main-content {
    padding: 2rem 0;
}

.content-wrapper {
    display: flex;
    gap: 2rem;
}

/* ========================================
   Sidebar
   ======================================== */

.sidebar {
    width: 320px;
    flex-shrink: 0;
}

.sidebar-section {
    background: var(--dark-2);
    border: 1px solid var(--gray-700);
    border-radius: 10px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.sidebar-title {
    padding: 1rem 1rem 0.5rem;
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--gray-500);
    text-transform: uppercase;
    border-bottom: 1px solid var(--gray-700);
}

.category-list, .model-list {
    max-height: 400px;
    overflow-y: auto;
}

.category-item, .model-item {
    display: flex;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--gray-700);
    transition: var(--transition-fast);
    cursor: pointer;
    gap: 0.75rem;
}

.category-item:last-child,
.model-item:last-child {
    border-bottom: none;
}

.category-item:hover,
.model-item:hover {
    background: rgba(255, 165, 0, 0.1);
}

.category-item.active:hover,
.model-item.active:hover {
    background: rgba(255, 165, 0, 0.2);
}

.category-item i,
.model-item i {
    min-width: 30px;
    color: var(--gray-500);
    font-size: 1rem;
}

.category-item.active i,
.model-item.active i {
    color: var(--primary-color);
}

.category-item span,
.model-item .model-info h4 {
    flex: 1;
    font-size: 0.95rem;
    font-weight: 500;
}

.category-item span {
    color: var(--gray-500);
    font-size: 0.85rem;
    text-transform: none;
}

.model-item .model-info {
    text-align: left;
}

.model-item .model-info h4 {
    color: var(--white);
    line-height: 1.3;
}

.model-item .model-info span {
    display: block;
    color: var(--gray-500);
    font-size: 0.8rem;
}

/* ========================================
   Video Grid
   ======================================== */

.video-section {
    flex: 1;
    min-width: 0;
}

.video-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1rem;
}

.video-card {
    cursor: pointer;
    transition: var(--transition-fast);
}

.video-card:hover {
    transform: scale(1.02);
}

.video-thumbnail {
    position: relative;
    aspect-ratio: 16/9;
    background: var(--dark-3);
    border-radius: 8px;
    overflow: hidden;
    border: 2px solid var(--primary-color);
}

.video-preview-icon {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.5);
    opacity: 0;
    transition: var(--transition-fast);
}

.video-thumbnail:hover .video-preview-icon {
    opacity: 1;
}

.video-preview-icon i {
    color: var(--white);
    font-size: 2.5rem;
}

.video-duration {
    position: absolute;
    bottom: 0.5rem;
    right: 0.5rem;
    background: rgba(0, 0, 0, 0.8);
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--white);
    border-radius: 3px;
}

.video-rating {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background: rgba(30, 200, 30, 0.9);
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: #fff;
    border-radius: 3px;
}

.video-rating i {
    color: #ffd700;
    margin-right: 0.25rem;
}

.video-title {
    margin-top: 0.75rem;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--white);
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    min-height: 3rem;
}

.video-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: var(--gray-500);
}

.video-meta .model-name {
    color: var(--primary-color);
    font-weight: 600;
}

/* ========================================
   Load More Section
   ======================================== */

.load-more-section {
    text-align: center;
    padding: 2rem 0 3rem;
    margin: 2rem 0;
}

/* ========================================
   Footer
   ======================================== */

.site-footer {
    background: var(--dark-3);
    border-top: 1px solid var(--gray-700);
    padding: 3rem 0;
}

.footer-content {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-logo {
    font-family: var(--font-heading);
    font-size: 2rem;
    font-weight: 700;
    border: 2px solid var(--primary-color);
    padding: 0.5rem 1.5rem;
    border-radius: 50px;
    display: inline-flex;
    align-items: center;
}

.footer-logo-text {
    color: var(--primary-color);
}

.footer-tagline {
    color: var(--gray-500);
    font-size: 1rem;
    text-align: center;
}

.footer-social {
    display: flex;
    gap: 1rem;
}

.social-btn {
    width: 45px;
    height: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--dark-2);
    border: 1px solid var(--gray-700);
    border-radius: 50%;
    color: var(--gray-500);
    font-size: 1.2rem;
    transition: var(--transition-fast);
}

.social-btn:hover {
    background: var(--primary-color);
    border-color: var(--primary-color);
    color: var(--white);
}

.footer-copy {
    text-align: center;
    color: var(--gray-500);
    margin-bottom: 2rem;
}

.footer-links {
    display: flex;
    justify-content: center;
    gap: 2rem;
    flex-wrap: wrap;
}

.footer-link {
    color: var(--gray-500);
    font-size: 0.9rem;
    text-transform: uppercase;
    transition: var(--transition-fast);
}

.footer-link:hover {
    color: var(--primary-color);
}

/* ========================================
   Modals
   ======================================== */

.video-modal, .info-modal {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.9);
    z-index: 2000;
    align-items: center;
    justify-content: center;
    padding: 2rem;
}

.video-modal.active,
.info-modal.active {
    display: flex;
}

.modal-content {
    background: var(--dark-2);
    border: 1px solid var(--primary-color);
    border-radius: 10px;
    max-width: 900px;
    width: 100%;
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.modal-content .modal-close {
    position: absolute;
    top: 1rem;
    right: 1.5rem;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.2);
    border: none;
    border-radius: 50%;
    color: var(--white);
    font-size: 1.5rem;
    cursor: pointer;
    transition: var(--transition-fast);
    z-index: 10;
}

.modal-content .modal-close:hover {
    background: var(--primary-color);
}

.modal-content .modal-body {
    display: flex;
    flex-direction: column;
}

.modal-video-wrapper {
    background: var(--dark-3);
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 400px;
    border-bottom: 1px solid var(--gray-700);
    position: relative;
}

.video-placeholder {
    text-align: center;
    color: var(--gray-500);
}

.video-placeholder i {
    font-size: 4rem;
    margin-bottom: 1rem;
    background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.modal-info {
    padding: 1.5rem;
}

.modal-info h3 {
    font-size: 1.2rem;
    margin-bottom: 0.5rem;
    color: var(--white);
}

.modal-info p {
    color: var(--gray-500);
    font-size: 0.95rem;
    margin-bottom: 1rem;
}

.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

.info-header {
    padding: 1rem 1.5rem;
    background: var(--dark-3);
    border-bottom: 1px solid var(--gray-700);
}

.info-header h3 {
    font-size: 1rem;
    color: var(--white);
}

.info-body {
    padding: 1.5rem;
}

.info-row {
    display: flex;
    justify-content: space-between;
    padding: 0.75rem 0;
    border-bottom: 1px solid var(--gray-700);
}

.info-row:last-child {
    border-bottom: none;
}

.info-label {
    color: var(--gray-500);
    font-size: 0.9rem;
}

.info-value {
    color: var(--white);
    font-weight: 600;
}

.info-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
    padding: 1.5rem;
    background: var(--dark-3);
}

/* ========================================
   Notification Badge
   ======================================== */

.notification-badge {
    position: absolute;
    top: 2px;
    right: 2px;
    min-width: 15px;
    height: 15px;
    background: var(--primary-color);
    border: 2px solid var(--dark-1);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.65rem;
    font-weight: 700;
    color: var(--white);
}

/* ========================================
   Responsive
   ======================================== */

@media (max-width: 1200px) {
    .video-grid {
        grid-template-columns: repeat(3, 1fr);
    }

    .sidebar {
        width: 280px;
    }
}

@media (max-width: 992px) {
    .content-wrapper {
        flex-wrap: wrap;
    }

    .sidebar {
        width: 100%;
        max-width: 350px;
        order: 2;
    }

    .video-section {
        flex: 1;
        order: 1;
    }

    header h1.logo-text {
        font-size: 2.5rem;
    }

    .header-filters {
        flex-wrap: wrap;
    }

    .filter-btn {
        width: 100%;
    }
}

@media (max-width: 768px) {
    .nav-container {
        flex-wrap: wrap;
    }

    .nav-search {
        order: 3;
        max-width: 100%;
        margin-top: 0.5rem;
    }

    .nav-actions .nav-btn:not(.btn-user) {
        display: none;
    }

    .nav-actions .btn-user {
        display: flex;
        padding: 1rem 1.5rem;
        border-radius: 50px;
    }

    .search-header,
    .header-filters {
        flex-direction: column;
        align-items: center;
        gap: 1rem;
    }

    .header-filters .filter-group {
        flex-wrap: wrap;
        justify-content: center;
    }

    .filter-btn {
        min-width: 100px;
        padding: 0.6rem 1.2rem;
    }

    .video-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 0.75rem;
    }

    .sidebar {
        max-width: 100%;
    }

    .sidebar-section {
        margin-bottom: 1rem;
    }

    .content-wrapper {
        flex-wrap: wrap;
    }

    .sidebar {
        order: 1;
        width: 100%;
        max-width: 100%;
    }

    .video-section {
        order: 2;
    }

    .modal-body {
        flex-direction: column;
    }

    .modal-video-wrapper {
        min-height: 300px;
    }
}

@media (max-width: 480px) {
    .container {
        padding: 0 var(--spacing-sm);
    }

    .nav-logo {
        font-size: 1.2rem;
    }

    .header-content h1.logo-text {
        font-size: 2rem;
    }

    .video-grid {
        grid-template-columns: 1fr;
    }

    .modal-content {
        margin: 1rem;
        max-height: 100vh;
        max-width: 100vw;
    }

    .footer-content {
        flex-wrap: wrap;
        justify-content: center;
    }

    .footer-logo {
        font-size: 1.5rem;
        padding: 0.5rem 1rem;
    }

    .footer-social {
        gap: 0.75rem;
    }

    .social-btn {
        width: 40px;
        height: 40px;
    }

    .info-actions {
        flex-direction: column;
    }

    .info-actions .btn {
        width: 100%;
        justify-content: center;
    }
}

/* ========================================
   Animations
   ======================================== */

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: scale(0.95);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes pulse {
    0%, 100% {
        transform: scale(1);
    }
    50% {
        transform: scale(1.05);
    }
}

.video-modal, .info-modal {
    animation: fadeIn 0.3s ease forwards;
}

.modal-content {
    animation: fadeIn 0.3s ease forwards;
}

/* Glow effect on hover */
.category-item:hover,
.model-item:hover,
.filter-btn:hover,
.video-card:hover {
    animation: pulse 0.3s ease;
}

