function openInfoModal(videoTitle) {
    const modal = document.getElementById('infoModal');

    if (modal) {
        // Get video info
        const titleEl = document.getElementById('modal-video-title') || document.createElement('div');
        const titleDisplay = document.createElement('div');
        titleDisplay.style.cssText = 'font-size: 1.2rem; margin-bottom: 1rem; color: #fff;';
        titleDisplay.textContent = videoTitle;

        // Simulate API call for data
        const stats = getVideoStats(videoTitle);

        modal.querySelector('.info-row').forEach(function(row) {
            const label = row.querySelector('.info-label');
            const value = row.querySelector('.info-value');

            if (label && value) {
                if (label.textContent === 'Model') {
                    value.textContent = 'Model Name - Top Model';
                } else if (label.textContent === 'Views') {
                    value.textContent = formatViews(stats.views) + ' views';
                } else if (label.textContent === 'Date') {
                    value.textContent = stats.date;
                }
            }
        });

        modal.classList.add('active');

        // Add click event
        modal.addEventListener('click', function(e) {
            if (e.target === modal) {
                modal.classList.remove('active');
            }
        });
    }
}

